import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"蠱","description":"周易正義 - 蠱","frontmatter":{"title":"蠱","description":"周易正義 - 蠱"},"headers":[],"relativePath":"classics/zhengyi/018.md","filePath":"classics/zhengyi/018.md"}'),l={name:"classics/zhengyi/018.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>山風蠱</p></blockquote><blockquote><p>卦辭：元亨，利涉大川。先甲三日，後甲三日。</p></blockquote><blockquote><p>彖曰：蠱，剛上而柔下，巽而止，蠱。蠱，元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。</p></blockquote><h1 id="蠱" tabindex="-1">蠱 <a class="header-anchor" href="#蠱" aria-label="Permalink to “蠱”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“蠱元亨”至“後甲三日”。○正義曰：蠱者事也。有事營為，則大得亨通。有為之時，利在拯難，故“利涉大川”也。“先甲三日，後甲三日”者，甲者創制之令，既在有為之時，不可因仍舊令。今用創制之令以治於人，人若犯者，未可即加刑罰，以民未習，故先此宣令之前三日，殷勤而語之，又如此宣令之後三日，更丁寧而語之，其人不從，乃加刑罰也。其褚氏、何氏、周氏等並同鄭義，以為“甲”者造作新令之日，甲前三日，取改過自新，故用辛也。甲後三日，取丁寧之義，故用丁也。今案輔嗣《注》，“甲者，創制之令”，不雲創制之日。又《巽卦》九五“先庚三日，後庚三日”，輔嗣《注》：“申命令謂之庚”。輔嗣又云：“甲、庚皆申命之謂”。則輔嗣不以甲為創制之日，而諸儒不顧輔嗣《注》旨，妄作異端，非也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="蠱-剛上而柔下-​" tabindex="-1">蠱，剛上而柔下， ​ <a class="header-anchor" href="#蠱-剛上而柔下-​" aria-label="Permalink to “蠱，剛上而柔下， ​”">​</a></h3><p>王弼：上剛可以斷制，下柔可以施令。</p><h3 id="巽而止。蠱。-​" tabindex="-1">巽而止。蠱。 ​ <a class="header-anchor" href="#巽而止。蠱。-​" aria-label="Permalink to “巽而止。蠱。 ​”">​</a></h3><p>王弼：既巽又止，不競爭也。有事而無競爭之患，故可以有為也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“止蠱”。○正義曰：“剛上而柔下，巽而止蠱”者，此釋蠱卦之名，並明稱蠱之義也。以上剛能制斷，下柔能施令，巽順止靜，故可以有為也。褚氏雲：“蠱者惑也。物既惑亂，終致損壞，當須有事也，有為治理也。故《序卦》雲：‘蠱者事也。’”謂物蠱必有事，非謂訓蠱為事義當然也。</p><h3 id="蠱-元亨而天下治也。-​" tabindex="-1">蠱，元亨而天下治也。 ​ <a class="header-anchor" href="#蠱-元亨而天下治也。-​" aria-label="Permalink to “蠱，元亨而天下治也。 ​”">​</a></h3><p>王弼：有為而大亨，非天下治而何也？</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“元亨”之義。以有為而得“元亨”，是天下治理也。</p><h3 id="利涉大川-往有事也。-先甲三日-後甲三日-終則有始-天行也。-​" tabindex="-1">“利涉大川”，往有事也。“先甲三日，後甲三日”，終則有始，天行也。 ​ <a class="header-anchor" href="#利涉大川-往有事也。-先甲三日-後甲三日-終則有始-天行也。-​" aria-label="Permalink to ““利涉大川”，往有事也。“先甲三日，後甲三日”，終則有始，天行也。 ​”">​</a></h3><p>王弼：蠱者有事而待能之時也。可以有為，其在此時矣。物巳說隨，則待夫作制以定其事也。進德修業，往則亨矣。故“元亨，利涉大川”也。甲者，創制之令也。創制不可責之以舊，故先之三日，後之三日，使令治而後乃誅也。因事申令，終則復始，若天之行用四時也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“利涉大川，往有事也”者，釋“利涉大川”也。蠱者有為之時，拔拯危難，往當有事，故“利涉大川”。此則假外象以喻危難也。“先甲三日，後甲三日，終則有始天行”者，釋“先甲三日，後甲三日”之義也。民之犯令，告之巳終，更復從始，告之殷勤不巳，若天之行，四時既終，更復從春為始，象天之行，故云“天行也”。○注“蠱者”至“四時也”。○正義曰：“蠱者有事待能之時”者，物既蠱壞，須有事營為，所作之事，非賢能不可。故《經》雲“幹父之蠱”，幹則能也。“甲者創制之令”者。甲為十日之首，創造之令為在後諸令之首，故以創造之令謂之為甲。故漢時謂令之重者謂之“甲令”，則此義也。“創制不可責之以舊”者，以人有犯令而致罪者，不可責之舊法，有犯則刑。故須先後三日，殷勤語之，使曉知新令，而後乃誅，誅謂兼通責讓之罪，非專謂誅殺也。</p><h2 id="《象》曰-山下有風-蠱。君子以振民育德。-​" tabindex="-1">《象》曰：山下有風，蠱。君子以振民育德。 ​ <a class="header-anchor" href="#《象》曰-山下有風-蠱。君子以振民育德。-​" aria-label="Permalink to “《象》曰：山下有風，蠱。君子以振民育德。 ​”">​</a></h2><p>王弼：蠱者，有事而待能之時也，故君子以濟民養德也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：必雲“山下有風”者，風能搖動，散佈潤澤。今“山下有風”，取君子能以恩澤下振於民，育養以德。“振民”，象“山下有風”；“育德”象山在上也。</p><h2 id="初六-幹父之蠱-有子-考無咎-厲終吉。-​" tabindex="-1">初六：幹父之蠱，有子，考無咎，厲終吉。 ​ <a class="header-anchor" href="#初六-幹父之蠱-有子-考無咎-厲終吉。-​" aria-label="Permalink to “初六：幹父之蠱，有子，考無咎，厲終吉。 ​”">​</a></h2><p>王弼：處事之首，始見任者也。以柔巽之質，幹父之事，能承先軌，堪其任者也，故曰“有子”也。任為事首，能堪其事，“考”乃無咎也，故曰“有子考無咎”也。當事之首，是以危也。能堪其事，故“終吉”。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“初六”至“厲終吉”。○正義曰：“幹父之蠱”者，處事之首，以柔巽之質幹父之事，堪其任也。“有子考無咎”者，有子既能堪任父事，“考”乃“無咎”也。以其處事之初，若不堪父事，則“考”有咎也。“厲終吉”者，厲，危也。既為事初，所以危也。能堪其事，所以“終吉”也。</p><h3 id="《象》曰-幹父之蠱-意承-考-也。-​" tabindex="-1">《象》曰：“幹父之蠱”，意承“考”也。 ​ <a class="header-anchor" href="#《象》曰-幹父之蠱-意承-考-也。-​" aria-label="Permalink to “《象》曰：“幹父之蠱”，意承“考”也。 ​”">​</a></h3><p>王弼：幹事之首，時有損益，不可盡承，故意承而已。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“幹父之蠱”義。凡堪幹父事，不可小大損益一依父命，當量事制宜以意承考而巳。對文父沒稱“考”，若散而言之，生亦稱“考”。若《康誥》雲：“大傷厥考心。”是父在稱考。此避幹父之文，故變雲“考也”。</p><h2 id="九二-幹母之蠱-不可貞。-​" tabindex="-1">九二：幹母之蠱，不可貞。 ​ <a class="header-anchor" href="#九二-幹母之蠱-不可貞。-​" aria-label="Permalink to “九二：幹母之蠱，不可貞。 ​”">​</a></h2><p>王弼：居於內中，宜幹母事，故曰“幹母之蠱”也。婦人之性難可全正，宜屈已剛。既幹且順，故曰“不可貞”也。幹不失中，得中道也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：居內處中，是幹母事也。“不可貞”者，婦人之性難可全正，宜屈己剛，不可固守貞正，故云“不可貞”也。</p><h3 id="《象》曰-幹母之蠱-得中道也。-​" tabindex="-1">《象》曰：“幹母之蠱”，得中道也。 ​ <a class="header-anchor" href="#《象》曰-幹母之蠱-得中道也。-​" aria-label="Permalink to “《象》曰：“幹母之蠱”，得中道也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“得中道”者，釋“幹母之蠱”義。雖不能全正，猶不失在中之道，故云“得中道”也。</p><h2 id="九三-幹父之蠱-小有悔-無大咎。-​" tabindex="-1">九三：幹父之蠱，小有悔，無大咎。 ​ <a class="header-anchor" href="#九三-幹父之蠱-小有悔-無大咎。-​" aria-label="Permalink to “九三：幹父之蠱，小有悔，無大咎。 ​”">​</a></h2><p>王弼：以剛幹事，而無其應，故“有悔”也。履得其位，以正幹父，雖“小有悔”，終無大咎。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“幹父之蠱小有悔”者，以剛幹事而無其應，故“小有悔”也。“無大咎”者，履得其位，故終無大咎也。</p><h3 id="《象》曰-幹父之蠱-終無咎也。-​" tabindex="-1">《象》曰：“幹父之蠱”，終無咎也。 ​ <a class="header-anchor" href="#《象》曰-幹父之蠱-終無咎也。-​" aria-label="Permalink to “《象》曰：“幹父之蠱”，終無咎也。 ​”">​</a></h3><h2 id="六四-裕父之蠱-往見吝。-​" tabindex="-1">六四：裕父之蠱，往見吝。 ​ <a class="header-anchor" href="#六四-裕父之蠱-往見吝。-​" aria-label="Permalink to “六四：裕父之蠱，往見吝。 ​”">​</a></h2><p>王弼：體柔當位，幹不以剛而以柔和，能裕先事者也。然無其應，往必不合，故曰“往見吝”。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“見吝”。○正義曰：“裕父之蠱”者，體柔當位，幹不以剛，而以柔和能容裕父之事也。“往見吝”者，以其無應，所往之處，見其鄙吝，故“往未得”也。</p><h3 id="《象》曰-裕父之蠱-往未得也。-​" tabindex="-1">《象》曰：“裕父之蠱”，往未得也。 ​ <a class="header-anchor" href="#《象》曰-裕父之蠱-往未得也。-​" aria-label="Permalink to “《象》曰：“裕父之蠱”，往未得也。 ​”">​</a></h3><h2 id="六五-幹父之蠱-用譽。-​" tabindex="-1">六五：幹父之蠱，用譽。 ​ <a class="header-anchor" href="#六五-幹父之蠱-用譽。-​" aria-label="Permalink to “六五：幹父之蠱，用譽。 ​”">​</a></h2><p>王弼：以柔處尊，用中而應，承先以斯，用譽之道也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“用譽”。○正義曰：“幹父之蠱用譽”者，以柔處尊，用中而應，以此承父，用有聲譽。</p><h3 id="《象》曰-幹父用譽-承以德也。-​" tabindex="-1">《象》曰：“幹父用譽”，承以德也。 ​ <a class="header-anchor" href="#《象》曰-幹父用譽-承以德也。-​" aria-label="Permalink to “《象》曰：“幹父用譽”，承以德也。 ​”">​</a></h3><p>王弼：以柔處中，不任威力也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“幹父用譽”之義。奉承父事，唯以中和之德，不以威力，故云“承以德”也。</p><h2 id="上九-不事王侯-高尚其事。-​" tabindex="-1">上九：不事王侯，高尚其事。 ​ <a class="header-anchor" href="#上九-不事王侯-高尚其事。-​" aria-label="Permalink to “上九：不事王侯，高尚其事。 ​”">​</a></h2><p>王弼：最處事上而不累於位，“不事王侯，高尚其事”也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：最處事上，不復以世事為心，不繫累於職位，故不承事王侯，但自尊高慕尚其清虛之事，故云“高尚其事”也。</p><h3 id="《象》曰-不事王侯-志可則也。-​" tabindex="-1">《象》曰：“不事王侯”，志可則也。 ​ <a class="header-anchor" href="#《象》曰-不事王侯-志可則也。-​" aria-label="Permalink to “《象》曰：“不事王侯”，志可則也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“不事王侯”之義。身既不事王侯，志則清虛高尚，可法則也。</p>',65)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
